    const npiece = state.boardState[dst.y][dst.x];
    return npiece !== null && piece.owner !== npiece.owner;
}
function checkPosIsEmptyOrEnemy(piece, state, dst) {
    const npiece = state.boardState[dst.y][dst.x];
    return npiece === null || piece.owner !== npiece.owner;
